def complexFramePiLpEquivFin (p : ℝ≥0∞) [Fact (1 ≤ p)] (n : ℕ) :
    PiLp p (fun _ : FrameIndex n => ℂ) ≃ₗᵢ[ℂ] PiLp p (fun _ : Fin (4 ^ n) => ℂ) :=
  LinearIsometryEquiv.piLpCongrLeft p ℂ ℂ (frameIndexEquivFin n)

